const data = $input.first().json;
const carteras = data.carteras || [];

let totalPagaron = 0, totalSinMatch = 0, totalPendientes = 0;
const detalle = [];

for (const c of carteras) {
  if (c.error) {
    detalle.push({ sucursal: c.sucursal, error: c.error });
    continue;
  }
  totalPagaron    += (c.pagaron || []).length;
  totalSinMatch   += (c.sin_match || []).length;
  totalPendientes += (c.pendientes_hoy_sin_pago || []).length;
  detalle.push({
    sucursal: c.sucursal,
    cartera: c.nombre,
    pagaron: (c.pagaron || []).length,
    sin_match: (c.sin_match || []).length,
    pendientes_sin_pago: (c.pendientes_hoy_sin_pago || []).length,
    sin_match_detalle: c.sin_match || [],
    pendientes_detalle: c.pendientes_hoy_sin_pago || [],
  });
}

return [{
  json: {
    fecha: data.fecha,
    totales: { pagaron: totalPagaron, sin_match: totalSinMatch, pendientes_sin_pago: totalPendientes },
    carteras: detalle,
  }
}];

const d = $input.first().json;
let texto = `📊 Cruce de cobranza — ${d.fecha}\n\n`;
texto += `Pagaron (match confirmado): ${d.totales.pagaron}\n`;
texto += `Sin match (revisar a mano): ${d.totales.sin_match}\n`;
texto += `Pendientes sin pago hoy: ${d.totales.pendientes_sin_pago}\n\n`;

for (const c of d.carteras) {
  if (c.error) { texto += `⚠️ ${c.sucursal}: ${c.error}\n`; continue; }
  texto += `— ${c.sucursal} (${c.cartera}) —\n`;
  texto += `  Pagaron: ${c.pagaron} | Sin match: ${c.sin_match} | Pendientes: ${c.pendientes_sin_pago}\n`;
  if (c.sin_match_detalle.length) {
    texto += `  Revisar:\n`;
    for (const s of c.sin_match_detalle) texto += `    - Recibo ${s.recibo} (${s.cliente}, L${s.monto}): ${s.motivo}\n`;
  }
  texto += `\n`;
}

return [{ json: { ...d, reporte_texto: texto } }];
